def bookpage(page,title=None):
 r=R[-1];r['sourceIds']=['bio-pep8down-images','bio-pep8down-start2026'];r['evidenceStatus']='第三方学生书图像逐页核对；未核版权页印次';r['evidencePages']=[page]
 if title:r['evidenceTitles']=[title]
add('asexual','8下','第六单元 第一章 生物的生殖','比较几种生物的无性生殖方式','小实验','reproduction',[opt('organism','模型材料',[('leaf','椒草叶营养繁殖'),('paramecium','草履虫分裂'),('hydra','水螅出芽')]),num('stage','观察阶段',0,3,0)],'通过不同实例识别无性生殖的共同特点及结构差异。','生殖过程图卡|叶片、单细胞、水螅模型|比较记录表','按阶段排列各材料的过程图。|分别辨认营养器官、细胞分裂或芽体形成。|追踪新个体与亲代的关系，查明是否经过两性生殖细胞结合。','椒草可由叶形成新植株；草履虫分裂形成两个个体；水螅芽体长成后可脱离。|分裂前遗传物质先复制，不能说两个后代各只获得一半完整遗传信息。','三种方式虽结构不同，都不经两性生殖细胞结合，属于无性生殖。','营养繁殖、分裂生殖与出芽生殖区别|遗传物质复制和分配','不能把个体生长当作生殖|不能把草履虫分裂与形成配子的减数过程混同',('草履虫分成两个个体后，每个个体的遗传物质是残缺的一半吗？','不是。正常分裂前遗传物质复制，再分配到新个体中，完整遗传信息得以保持。'),('比较椒草叶长出新植株和水螅芽体脱离，说明共同点。','辨认新个体的来源和有无两性生殖细胞结合。','两者由亲代的营养部分形成新个体。','共同点是无性生殖，具体形成方式分别为营养繁殖和出芽。'),'两者都属于无性生殖，不能因为外形不同就认为共同点不存在。',config={'variant':'asexual'},safety='使用图卡或教学模型；实物观察不擅自采集野生动物。');bookpage(3,'几种生物的生殖方式')
add('egg-pores','8下','第六单元 第一章 生物的生殖','设计实验观察卵壳上的气孔','小实验','anatomy',[opt('water','比较条件',[('warm','适度温水'),('room','室温水')]),opt('observation','观察记录',[('bubbles','局部出现细小气泡'),('none','暂未观察到气泡')])],'用可观察的现象为卵壳允许气体通过提供证据，并认识证据边界。','鸡卵或卵壳教学材料|教师准备的适度温水与室温水|透明容器|放大镜','依据卵壳应有气体交换通道提出可检验的方案。|在教师指导下比较温水与室温条件，保持材料和观察时长可比。|记录气泡出现位置与时间，不把未观察到气泡直接记为没有气孔。|讨论气泡来源及试验不能测定的量。','温水条件可使卵内气体受热膨胀，从部分孔道逸出形成气泡。|现象受卵状态、水温及观察时间影响，气泡个数不等于气孔总数。','气体能够从卵壳通过的现象支持卵壳具有通气孔道，不据此估算全部气孔数。','实验现象与结构解释|阴性观察不等于结构不存在','不要把每个气泡当一个独立气孔|不虚构测得全部卵壳气孔数量',('看到5个气泡能说明卵壳只有5个气孔吗？','不能。一个孔可先后放出多个气泡，有些孔没有可见气泡；气泡计数不能作为气孔总数。'),('温水中同一区域连续出现气泡，应怎样作答？','描述可重复观察的气体逸出现象。','温度变化可使内部气体膨胀，气体经孔道排出。','支持存在通气结构，但不能推算气孔总数。'),'现象支持卵壳具有通气孔道；气泡数不是气孔总数。',config={'specimen':'egg-pores'},safety='水温由教师控制，避免烫伤；不用沸水和密闭加压装置，实验材料不食用。');bookpage(15,'试一试：设计实验验证卵壳上的气孔')
add('traits','8下','第六单元 第二章 生物的遗传与变异','观察生物性状并识别相对性状','小实验','genetics',[opt('pair','比较材料',[('pea','豌豆高茎和矮茎'),('tomato','番茄红果与黄果'),('different','番茄果色与果形'),('human','人的眼睑形态观察')]),opt('basis','判断依据',[('same','同种生物的同一性状'),('appearance','只因外表看起来不同')])],'区分性状与相对性状，避免把全部人类外观特征简单归为单基因遗传。','植物性状图卡|比较表|公开非识别性形态示意','先说明物种，再明确比较哪一种性状。|判断差异是否为同一性状的不同表现。|区分观察到的形态与尚未验证的遗传解释。','同种豌豆茎高的高与矮属于同一性状的不同表现。|同一番茄的果色与果形不是同一性状。|人类许多外貌特征遗传复杂，观察差异不等于可直接套用单基因模型。','相对性状需在同种生物的同一性状内比较不同表现。','物种与性状两个前提|性状还受环境影响','不能把不同性状拼成相对性状|不能用眼皮或耳垂直接推断亲子关系',('番茄红色果实与椭圆形果实构成一对相对性状吗？','不构成，红色描述果色，椭圆描述果形，是不同性状。'),('豌豆高茎与矮茎是否为相对性状，说明理由。','先核对物种都是豌豆。','比较指标均为茎的高矮，是同一性状。','高与矮为不同表现，满足相对性状定义。'),'属于相对性状；判断依据是同种生物、同一性状、不同表现。',config={'variant':'traits'});bookpage(21,'生物的不同性状')
add('genetic-material','8下','第六单元 第二章 生物的遗传与变异','观察染色体、DNA和基因的关系','小实验','genetics',[opt('level','观察层次',[('cell','细胞与细胞核'),('chromosome','染色体'),('dna','DNA'),('gene','基因片段')]),num('pairs','二倍体模型染色体对数',1,5,3)],'建立细胞核、染色体、DNA与基因的层级关系，区分结构和数量。','原创放大结构模型|染色体卡片|层级标签','从细胞定位到细胞核及染色体。|观察染色体与DNA、蛋白质的关系。|用DNA局部区段表示基因，避免把一条染色体当作一个基因。|以简化对数模型练习体细胞与配子的数量关系。','染色体主要由DNA和蛋白质构成；DNA包含遗传信息。|一条DNA分子可有多个基因，基因是有遗传效应的DNA片段。','染色体、DNA、基因不是同一层次概念；本页对数为简化模型，非某个实际物种的核型。','染色体与DNA关系|基因在DNA上的位置|成对的是同源染色体','不能把每条染色体画成只含一个基因|不要把模型3对当成人体实际数量',('人体正常体细胞23对染色体是否意味着只有23对基因？','不意味着，一条染色体的DNA上有许多基因；染色体对数不是基因数。'),('简化模型有3对染色体，形成正常配子后该模型配子应含几条？','3对即6条，配子只取每对中的一条。','配子染色体数是该正常体细胞模型的一半。','得到3条，受精后可恢复为3对。'),'该简化配子模型含3条染色体；这不是人体真实配子数量。',config={'variant':'material'});bookpage(27,'染色体、DNA和基因的关系')
add('karyotype','8下','第六单元 第二章 生物的遗传与变异','观察典型人类染色体组成','小实验','genetics',[opt('combination','性染色体示意',[('XX','典型XX'),('XY','典型XY')]),opt('cell','细胞类型',[('body','正常二倍体体细胞'),('gamete','形成配子后的组成')]),opt('gamete','本次配子性染色体',[('X','X'),('Y','Y')])],'区分常染色体、性染色体与正常配子的数量，理解典型模型的范围。','原创核型示意图|常染色体与性染色体卡片|观察记录表','在典型体细胞示意中识别22对常染色体与1对性染色体。|模拟每对分离到配子，比较总数变化。|区分卵细胞典型X与精子可能X或Y的模型。','典型体细胞含46条染色体，其中44条常染色体与2条性染色体。|正常配子含23条，即22条常染色体及1条性染色体。|本模型不概括所有染色体或性发育差异。','染色体数与配子形成有关，不能仅由外貌或有限示意替代医学核型分析。','23对与23条的区别|常染色体和性染色体|典型模型范围','不能说女性没有性染色体|不能把少见差异否定为不可能',('典型XY体细胞形成的一个精子是否通常同时含X和Y？','不是。正常配子含其中的一条性染色体，可能为X或Y，另含22条常染色体。'),('典型人类精子含22条常染色体和一条Y，总计多少条？','将常染色体和性染色体都计入。','22+1=23。','23条不是23对，受精后才恢复典型成对状态。'),'该精子共23条染色体，其中1条为Y。',config={'variant':'karyotype'});bookpage(39,'男性和女性的染色体')
add('origin-evidence','8下','第六单元 第三章 生物的进化','分析原始地球生命形成的证据','拓展探究','anatomy',[opt('part','观察装置环节',[('water','加热水与水蒸气'),('gas','气体与放电区域'),('cool','冷凝与循环'),('collect','收集并检验产物')]),opt('claim','比较解释',[('supported','某些条件可形成简单有机物'),('life','实验已制造生命'),('unique','已确定唯一的真实起源过程')])],'区分模拟实验的观察证据、可支持的推论与尚不能回答的问题。','原始大气情景资料|米勒型装置原创示意|结论辨析卡','按水蒸气、气体处理、冷凝、收集标记装置流程。|区分装置人为设定的条件与实际古环境证据。|核对氨基酸等简单有机物的产物证据。|比较不同结论是否超出实验范围。','特定模拟条件下可形成某些简单有机物。|产生简单有机物不等于产生细胞或生命。|原始大气组成、环境和生命起源路线仍有研究空间。','模拟实验支持某些无机条件形成简单有机物的可能性，不能单独证明完整生命起源过程。','实验条件与自然历史区别|有机物不等于生命|证据强度与结论范围','不把氨基酸等同蛋白质或细胞|不把示意装置当作家用操作教程',('检测到氨基酸能说明已制造生命吗？','不能。氨基酸是简单有机物，形成生命还涉及复杂分子、结构与功能体系等问题。'),('某装置在设定气体和能量条件下得到简单有机物，怎样规范表述？','先写清人为设定的条件和实际检测到的产物。','实验支持这些条件下可以发生相关化学转化。','不扩大为自然界唯一过程，更不说已制造生命。'),'该结果支持特定条件下简单有机物形成的可能性，不证明完整生命起源。',config={'specimen':'origin'},safety='只做装置与证据模型阅读；不搭建高压放电或可燃气体装置。');bookpage(52,'原始地球上生命形成的推测')
add('human-comparison','8下','第六单元 第三章 生物的进化','比较现代类人猿与人类的特征','小实验','anatomy',[opt('feature','比较特征',[('movement','主要运动方式'),('skull','颅骨与脑的相对特征'),('communication','语言与文化活动')]),opt('relationship','关系解释',[('branch','现生类群具有共同祖先'),('direct','人由现代黑猩猩直接变成')])],'用多种特征及证据解释亲缘关系，避免直线演化与优劣排序。','原创骨架与轮廓比较图|化石和分子证据资料|比较记录表','先比较可观察的运动及结构特征。|区分共同特征与各自演化的差异。|结合化石和分子证据解释共同祖先。|用分支关系表达现代人和现代类人猿的关系。','人类稳定直立行走与骨骼结构相联系。|现代人类与现代类人猿各有自己的演化历史。|某一结构相似不能独立确定全部亲缘细节。','人类与其他现生类人猿共享演化祖先，不是由某个现存类人猿物种直接变来。','共同祖先与分支演化|多证据互相支持','不把现存生物排成高低阶梯|不以单一外貌特征评价个体价值',('“人类由今天的黑猩猩进化而来”准确吗？','不准确。现代人类与现代黑猩猩具有共同祖先，之后在不同分支上演化。'),('图中人类与黑猩猩共享一个分支节点，如何解释？','节点代表推断的共同祖先。','两条现生分支都经历了演化。','不能把其中一个现生类群视为另一个的直接祖先。'),'两者有共同祖先，各自经历演化，现代黑猩猩不是现代人的直接祖先。',config={'specimen':'human-comparison'});bookpage(71,'比较现代类人猿与人类')
add('species-register','8下','第六单元 第四章 生物多样性及其保护','比较不同年度物种名录记录','拓展探究','survey',[num('earlier','较早名录记录数',0,20000,1000,100,'种'),num('later','较后名录记录数',0,20000,1200,100,'种'),opt('sameScope','口径是否一致',[('yes','范围与分类口径可比'),('no','范围或分类标准不同')]),opt('explanation','变化解释',[('record','调查或分类知识发生更新'),('population','直接证明所有野外种群恢复')])],'统计名录记录差异，区分知识更新、物种数与种群数量变化。','公开物种名录|发布年份及分类说明|统计表','记录资料来源、年份和地域范围。|核对分类口径及同物异名等变化。|计算可比较记录的数量差，保留原始数字。|讨论增加可能来自新发现、新记录和分类修订等，不直接等同生态恢复。','不同年度名录记录数可能改变。|物种名录不直接给出每个物种的野外个体数量。','名录统计要先统一口径，记录数增加不能单独证明野外种群恢复。','物种数与个体数不同|统计口径一致|资料更新与自然变化区分','不把示例数当中国真实统计|不能用名录总数代替濒危程度',('名录增加100种能证明生态系统新增100个稳定种群吗？','不能。可能是调查发现、分类修订或记录范围变化，还需野外分布和种群证据。'),('口径相同的教学名录由1000种变为1200种，解释差值。','数据为明确教学样例，并非我国实测统计。','差值=1200−1000=200种。','只表示名录增加200条物种记录，生态状况需其他证据。'),'该教学名录增加200种记录，不能据此断言野外种群全面恢复。',config={'variant':'species-register'});bookpage(79,'我国的物种多样性')
add('invasive-species','8下','第六单元 第四章 生物多样性及其保护','调查外来入侵风险并比较保护措施','拓展探究','ecology',[opt('status','所调查物种状态',[('native','本地原生种'),('introduced','外来但未证实造成危害'),('invasive','已有可靠入侵危害证据')]),opt('pathway','情景途径',[('release','随意放生'),('trade','运输或引种携带'),('contained','合规封闭管理')]),opt('action','保护行动',[('habitat','保护原生境并报告异常'),('exsitu','合规迁地保存作为补充'),('release','自行放生或扩大引种')])],'依据来源、定殖与危害证据区分外来种和入侵种，并评价保护方案。','本地官方物种资料|观察记录与位置图|保护措施卡','查阅本地区权威资料，不凭外形自行断定入侵种。|记录物种来源、分布及可核实的生态影响。|分析传播途径和已有管理要求。|比较就地保护、迁地保护及不当放生的后果。','不是所有外来物种都已造成入侵危害。|入侵可通过竞争、捕食或病原传播等影响原生生态关系。|就地与迁地保护各有作用，不能简单相互替代。','保护行动应依据当地证据和管理要求；不随意放生，不自行清除未确认物种。','外来与入侵区别|就地保护和迁地保护|传播途径管理','不能把全部外来种等同入侵种|不能凭网页模型批准野外释放',('外来植物在校园栽种就一定属于入侵种吗？','不一定。还需核对定殖扩散及造成危害的可靠证据和当地管理认定。'),('某外来动物已有入侵危害记录，有人建议放入附近河流，如何评价？','先确认当地可靠记录与管理要求。','释放可增加传播和生态风险。','拒绝自行放生，向教师或相关管理部门反映。'),'不能自行放生；应依可靠证据和当地管理要求处理。',config={'variant':'invasive'},safety='只调查和记录，不徒手接触未知生物，不自行捕杀、采集或放生。');bookpage(85,'外来入侵物种如何威胁生物多样性？|保护生物多样性的措施')
add('sexual-comparison','8下','第六单元 第一章 生物的生殖','比较几种动物的有性生殖','拓展探究','reproduction',[opt('animal','教材情景',[('hydra','水螅'),('locust','蝗虫'),('fish','斗鱼'),('bird','鸟')]),opt('stage','观察阶段',[('gametes','形成生殖细胞'),('fertilization','精卵结合'),('zygote','受精卵与发育')])],'用精卵结合辨认有性生殖，比较受精方式及其环境联系。','动物生殖过程资料卡|配子与受精卵模型|比较表','查明精子和卵细胞的来源与结合地点。|区分体内受精、体外受精与卵的产出位置。|比较不同动物仍具有的共同生殖环节。','模型中的蝗虫和鸟通常为体内受精，斗鱼及水螅示例为体外结合。|体内受精不等于胎生；鸟虽然体内受精，仍产卵。','有性生殖的核心是两性生殖细胞结合，不能只按是否产卵判断受精方式。','受精方式与发育方式不同|精卵结合与遗传信息传递','不要把卵生等同体外受精|不要把某个动物的方式套用全部动物',('鸟卵在体外孵化意味着鸟在体外受精吗？','不意味着，鸟通常在体内完成受精，之后产卵，卵在体外发育。'),('比较鸟与斗鱼的受精方式及共同环节。','分开记录受精地点与产卵地点。','鸟通常体内受精，斗鱼典型情景为体外受精。','两者均有精子与卵细胞结合形成受精卵。'),'受精地点不同，但都由精卵结合形成受精卵，属于有性生殖。',config={'variant':'sexual'},safety='使用资料与模型，不干扰动物繁殖或采集野生鸟卵。');bookpage(12,'几种动物的有性生殖')
add('transgene-evidence','8下','第六单元 第二章 生物的遗传与变异','分析转基因番茄对照实验的启示','拓展探究','genetics',[opt('group','比较植株',[('ordinary','普通植株'),('modified','教材中的导入基因植株')]),opt('temperature','教材处理情景',[('room','适宜温度'),('cold','低温处理')]),opt('controlled','其他条件',[('same','相同'),('different','同时改变光和水')])],'根据给定对照证据讨论基因与性状的关系，识别环境混杂。','教材情景的原创资料卡|两组植株模型|变量核对表','明确输入材料为教材给定情景，不是网页真实基因实验。|核对除基因状态外的材料、处理与观察条件。|比较同一环境下的现象，再讨论可以支持的结论。','给定教材情景中，两组植株低温后的表现可不同。|同时改变光照、水分会妨碍将差异归因于基因状态。','恰当对照的证据可支持基因影响性状，性状表现也受环境影响。','变量控制|基因与性状关系|模型结论的材料范围','不能认为导入任何基因都可得到预想性状|不能把模型当真实改造植株',('两组植株既基因状态不同又浇水不同，能把差异只归因于基因吗？','不能，水分成为混杂因素，需保持其余条件相同并设置重复。'),('两组植株同样低温处理，其他条件相同而表现不同，如何解释？','明确教材给定材料与控制条件。','比较处理后的同一观察指标。','结果支持所研究基因状态与该情景性状差异有关，不推广为所有基因。'),'在给定对照条件下，证据支持基因影响相关性状；结论限于所研究材料。',config={'variant':'transgene'});bookpage(23,'转基因番茄的启示')
add('breeding','8下','第六单元 第二章 生物的遗传与变异','比较几个育种实例','拓展探究','genetics',[opt('method','育种思路',[('selection','已有变异中选择繁育'),('hybrid','杂交组合亲本性状'),('mutation','诱变后选择'),('transgene','引入特定基因的研究')]),opt('claim','选择说明',[('screen','按目标筛选并验证后代'),('directed','认为需求会定向产生所需变异')])],'比较变异来源与人工选择作用，识别诱变不定向及需要验证的环节。','奶牛、小麦、甜椒、棉花育种资料卡|过程顺序卡|证据比较表','辨认案例利用已有变异、杂交组合、诱变或基因工程中的哪种思路。|在过程图中标出筛选与后代验证。|讨论哪些环节提供变异、哪些环节进行选择。','人工选择作用于存在的变异。|诱变可增加变异机会，但不会按人的需要定向产生指定性状。|目标性状仍需稳定性、环境适应性等验证。','不同育种思路获得变异的方式不同，共同需要选择与检验。','变异与选择不同|诱变不定向|性状稳定性需要证据','不能把人工需要当变异产生的原因|不能仅见一株高产就断定可稳定遗传',('诱变育种能保证每个后代都出现需要的性状吗？','不能，变异不定向且个体不同，需要筛选并验证。'),('某处理后出现多种性状，有人只保留目标类型，分别是哪两个环节？','区分产生变化与人为保留的行为。','变化提供选择材料，保留目标类型属于人工选择。','之后仍应验证后代及不同环境下表现。'),'变异提供材料，人工选择保留目标类型，两者不能混为一谈。',config={'variant':'breeding'},safety='仅比较公开育种原理，不进行辐射、化学诱变或转基因操作。');bookpage(46,'几个育种实例')
add('sex-ratio-data','8下','第六单元 第二章 生物的遗传与变异','分析人口性别比资料的统计口径','拓展探究','survey',[num('male','资料中的男性人数',0,100000,1050,50,'人'),num('female','资料中的女性人数',0,100000,1000,50,'人'),opt('scope','资料统计对象',[('population','全部常住人口'),('newborn','某时期活产新生儿')])],'按定义计算性别比并区分人口统计与受精时理论概率。','注明时间与地域的数据表|统计对象说明|计算记录表','核对计数对象、时间、范围及资料来源。|按每100名女性对应男性人数计算。|将人口结构统计与典型配子随机结合模型分开解释。','性别比常按男性人数÷女性人数×100表示。|总人口、出生人口和配子结合概率不是同一统计对象。|网页初值是教学样例，不是实际普查记录。','统计结果只描述所给资料，不能直接用于推定受精概率或归责某一性别。','分母定义|数量比与概率不同|统计口径一致','女性数为0时不能计算该比值|不能把总人口性别比当下一胎性别预测',('总人口性别比为105，能说受精时XY概率就是105%吗？','不能。105表示每100名女性对应105名男性，是人口数量比而非概率。'),('教学资料中男1050人、女1000人，计算男性人数对女性人数的比值。','定义是每100名女性对应的男性人数。','1050÷1000×100=105。','应写105名男性对应100名女性，不写男性概率105%。'),'教学资料性别比为105，即每100名女性对应105名男性；不是受精概率。',config={'variant':'sex-ratio'});bookpage(42,'分析和解释数据')
add('evidence-reasoning','8下','第六单元 第三章 生物的进化','评价演化证据并区分事实和观点','拓展探究','anatomy',[opt('case','资料情景',[('extinction','恐龙灭绝假说'),('migration','古人类迁徙推断')]),opt('statement','句子类型',[('observation','资料记载的观察结果'),('inference','依据结果提出的解释'),('overclaim','把单条线索当成唯一证明')])],'按证据来源、相关性和替代解释评价假说，区分观察与推断。','原创课堂资料卡|事实与推论标签|证据链记录表','先核对资料说明的测量或发现事实。|把由事实提出的解释单独列出。|检查其他证据与可能的替代解释。|根据新证据修正判断，不把课堂资料卡当最新研究结论全集。','发现某地点的化石与推断迁徙路径不是同一句话。|某种异常现象可以支持一类解释，但通常不足以独立排除所有其他解释。','科学解释需要证据支持和可修正性；事实记录、推测与确定程度应分别表达。','证据与观点区别|多证据支持|可检验性和替代解释','不能把有图有数字自动当结论成立|不要把教材介绍的假说都称为最新已证实定论',('在甲地发现古人类化石，能仅据此确定全部迁徙路线吗？','不能。发现地点是线索，迁徙路径还需年代、更多地点及其他证据支持。'),('资料卡说“某地发现化石”，有人说“因此已确定全部迁徙路线”，如何评价？','区分发现事实与路线推断。','一个地点不足以约束全部路线和时间顺序。','应补充年代和其他地点证据，限定结论。'),'化石发现是证据，完整迁徙路线是待更多证据检验的解释。',config={'specimen':'evidence'});bookpage(61,'评价证据与假说');R[-1]['evidencePages']=[61,74];R[-1]['evidenceTitles'].append('区分事实和观点')
add('cell-comparison','8下','第六单元 第四章 生物多样性及其保护','综合比较不同类群的细胞结构','拓展探究','anatomy',[opt('group','典型细胞模型',[('bacteria','典型细菌'),('fungus','真菌'),('plant','植物叶肉'),('animal','动物体细胞')]),opt('focus','比较结构',[('membrane','细胞膜'),('nucleus','成形细胞核'),('wall','细胞壁与叶绿体')])],'以细胞共同结构与差异联系生物多样性和统一性。','四类细胞原创模型|共同点与差异比较表|概念关系卡','按统一的结构项目比较四种模型。|区分细菌的DNA区域与真核细胞的成形细胞核。|核对叶绿体、细胞壁等结构出现的范围。|说明典型模型不能包含每类生物全部特殊情况。','四种模型均具有细胞膜、细胞质和遗传物质。|典型细菌没有成形细胞核；真菌、植物和动物细胞为真核细胞。|真菌无叶绿体；植物也不是每个细胞都有叶绿体。','共同细胞结构体现统一性，结构和功能差异体现多样性。','原核与真核区别|叶绿体不是所有细胞共有|病毒没有细胞结构','不能说真菌因为有细胞壁就能光合|典型细菌壁模型不否认少数无壁类群',('真菌有细胞壁，能由此断定它能光合作用吗？','不能。光合作用相关结构不能只由细胞壁推定；真菌没有叶绿体，营养方式与绿色植物不同。'),('比较典型细菌与动物体细胞，列一项共同点和一项差异。','用同一结构项目进行比较。','两者均有细胞膜和遗传物质。','动物细胞有成形细胞核，典型细菌没有。'),'共同具有细胞膜等基本结构；动物细胞有成形细胞核，典型细菌没有。',config={'specimen':'cell-comparison'});bookpage(89,'综合概括')
